package dev.industrialtechnology.space;
import net.minecraft.entity.*;import net.minecraft.entity.player.*;import net.minecraft.entity.item.EntityItem;import net.minecraft.world.*;import net.minecraft.item.ItemStack;import net.minecraft.nbt.NBTTagCompound;import net.minecraft.util.*;import net.minecraft.server.MinecraftServer;import net.minecraft.network.play.server.S1BPacketEntityAttach;import net.minecraftforge.common.DimensionManager;
public final class EntitySpaceRocket extends Entity {
    public final TileSpaceMachine control=new TileSpaceMachine(SpaceRegistry.LAUNCH);public String owner="";public int phase,ticks,destination;public ChunkCoordinates landing;private boolean claimed,transferQueued;private int burnCost,interpTicks;private double interpX,interpY,interpZ;
    public static final int LANDED=0,COUNTDOWN=1,ASCENT=2,DESCENT=3;
    public EntitySpaceRocket(World w){super(w);setSize(3,12);preventEntitySpawning=true;ignoreFrustumCheck=true;control.setWorldObj(w);}
    @Override protected void entityInit(){dataWatcher.addObject(20,(byte)0);dataWatcher.addObject(21,0);dataWatcher.addObject(22,(byte)0);}
    public boolean shuttle(){return worldObj.isRemote?dataWatcher.getWatchableObjectByte(22)!=0:ShuttleVehicle.is(control);}
    public void updateGeometry(){boolean s=shuttle();setSize(s?24:3,s?56.1f:12);if(!worldObj.isRemote){dataWatcher.updateObject(22,(byte)(s?1:0));rotationYaw=ShuttleVehicle.yaw(control);}}
    public int visualPhase(){return worldObj.isRemote?dataWatcher.getWatchableObjectByte(20):phase;}public int visualTicks(){return worldObj.isRemote?dataWatcher.getWatchableObjectInt(21):ticks;}
    public boolean prepare(EntityPlayerMP p){String error=RocketTravel.check(control,p);if(!RocketTravel.ready(error)){control.status=error;return false;}destination=RocketTravel.destination(control);WorldServer to=RocketTravel.world(destination);NBTTagCompound v=RocketTravel.vehicle(control);int x=v.getInteger("HomeX"),z=v.getInteger("HomeZ");if(destination!=0){long seed=to.getSeed();x=(int)((seed>>>8)%400)-200;z=(int)((seed>>>24)%400)-200;}
        updateGeometry();landing=RocketTravel.landing(to,x,z,shuttle());if(landing==null){control.status="No safe terrain landing site in bounded search; launch cancelled";return false;}
        if(!FlightLedger.get(worldObj).claim(v.getString("RocketId"),getUniqueID().toString())){control.status="This vehicle identity is already active";return false;}claimed=true;
        if(worldObj.provider.dimensionId==0&&!v.hasKey("HomeX")){v.setInteger("HomeX",(int)Math.floor(posX));v.setInteger("HomeZ",(int)Math.floor(posZ));}
        burnCost=RocketTravel.cost(control);phase=COUNTDOWN;ticks=0;control.owner=owner.isEmpty()?p.getUniqueID().toString():owner;DimensionActivity.exempt(worldObj,SpaceConfig.countdown+SpaceConfig.ascent+100);DimensionActivity.exempt(to,SpaceConfig.ascent+SpaceConfig.descent+200);return true;
    }
    private EntityPlayerMP passenger(){for(Object o:MinecraftServer.getServer().getConfigurationManager().playerEntityList){EntityPlayerMP p=(EntityPlayerMP)o;if(p.getUniqueID().toString().equals(owner))return p;}return null;}
    public void syncPassenger(EntityPlayerMP p){p.playerNetServerHandler.sendPacket(new S1BPacketEntityAttach(0,p,this));}
    @Override public void onUpdate(){super.onUpdate();updateGeometry();motionX=motionY=motionZ=0;if(worldObj.isRemote){if(interpTicks>0){setPosition(posX+(interpX-posX)/interpTicks,posY+(interpY-posY)/interpTicks,posZ+(interpZ-posZ)/interpTicks);interpTicks--;}if(visualPhase()==ASCENT||visualPhase()==DESCENT)SpaceEffects.particles(this);return;}
        control.setWorldObj(worldObj);control.xCoord=(int)Math.floor(posX);control.yCoord=(int)Math.floor(posY)-1;control.zCoord=(int)Math.floor(posZ);
        NBTTagCompound v=RocketTravel.vehicle(control);if(v==null){setDead();return;}if(!claimed){if(!FlightLedger.get(worldObj).claim(v.getString("RocketId"),getUniqueID().toString())){setDead();return;}claimed=true;}
        if(phase==LANDED){dataWatcher.updateObject(20,(byte)phase);return;}EntityPlayerMP p=passenger();if(p==null)return; // Offline flights persist without advancing or spending fuel.
        if(p.worldObj!=worldObj||p.getDistanceSqToEntity(this)>(shuttle()?16384:1024)){phase=LANDED;control.status="Flight stopped: passenger unavailable";return;}
        if(riddenByEntity!=p){if(phase==COUNTDOWN){phase=LANDED;control.status="Countdown cancelled: passenger dismounted";return;}p.mountEntity(this);syncPassenger(p);}
        ticks++;if(riddenByEntity==p&&(ticks<=5||ticks%20==0))syncPassenger(p);if(phase==COUNTDOWN){control.status="Countdown: "+Math.max(0,(SpaceConfig.countdown-ticks+19)/20)+"s";if(ticks>=SpaceConfig.countdown){if(!RocketTravel.clear(control)||!RocketTravel.pad(control)||control.tanks[0].getFluidAmount()<burnCost||control.tanks[1].getFluidAmount()<burnCost*SpaceConfig.oxygenRatio){phase=LANDED;control.status="Launch revalidation failed";p.mountEntity(null);return;}control.tanks[0].drain(burnCost,true);control.tanks[1].drain(burnCost*SpaceConfig.oxygenRatio,true);phase=ASCENT;ticks=0;}}
        else if(phase==ASCENT){setPosition(posX,posY+Math.min(2.4,.012*ticks+.02),posZ);fallDistance=0;if(ticks>=SpaceConfig.ascent&&!transferQueued){transferQueued=true;dev.industrialtechnology.core.ServerWork.enqueue(()->{transferQueued=false;if(!isDead&&phase==ASCENT){EntityPlayerMP live=passenger();if(live!=null&&live.worldObj==worldObj)transfer(live);}});}}
        else if(phase==DESCENT){double goal=landing.posY;setPosition(posX,Math.max(goal,posY-Math.max(.06,Math.min(1.6,(posY-goal)*.025))),posZ);fallDistance=0;if(posY<=goal+.01||ticks>=SpaceConfig.descent*3){setPosition(landing.posX+.5,goal,landing.posZ+.5);phase=LANDED;ticks=0;control.landed=true;control.target=2;control.returnReserve=false;p.mountEntity(null);double exitX=posX+(shuttle()?15:2.1);int exitY=worldObj.getTopSolidOrLiquidBlock((int)Math.floor(exitX),(int)Math.floor(posZ));p.playerNetServerHandler.setPlayerLocation(exitX,Math.max(goal,exitY),posZ,p.rotationYaw,0);control.status="Landed. Right click rocket to plan return.";}}
        if(!isDead){dataWatcher.updateObject(20,(byte)phase);dataWatcher.updateObject(21,ticks);if(riddenByEntity!=null)updateRiderPosition();}
    }
    private void transfer(EntityPlayerMP p){WorldServer to=RocketTravel.world(destination);double high=landing.posY+90;NBTTagCompound n=new NBTTagCompound();writeToNBT(n);p.mountEntity(null);MinecraftServer.getServer().getConfigurationManager().transferPlayerToDimension(p,destination,new RocketTravel.LandingTeleporter(to,landing.posX+.5,high+2,landing.posZ+.5));
        EntitySpaceRocket next=new EntitySpaceRocket(to);next.readFromNBT(n);next.dimension=destination;next.control.setWorldObj(to);next.phase=DESCENT;next.ticks=0;next.claimed=true;next.setPosition(landing.posX+.5,high,landing.posZ+.5);setDead();to.spawnEntityInWorld(next);p.mountEntity(next);next.syncPassenger(p);p.fallDistance=0;
    }
    @Override public void setPositionAndRotation2(double x,double y,double z,float yaw,float pitch,int increments){if(worldObj.isRemote){interpX=x;interpY=y;interpZ=z;interpTicks=Math.max(1,Math.min(5,increments));rotationYaw=yaw;rotationPitch=pitch;}else super.setPositionAndRotation2(x,y,z,yaw,pitch,increments);}
    @Override public double getMountedYOffset(){return shuttle()?43:8.5;}
    @Override public void updateRiderPosition(){if(riddenByEntity!=null){int f=ShuttleVehicle.facing(control);double dx=worldObj.isRemote?Math.sin(Math.toRadians(rotationYaw))*9.5:LaunchFacilityPlan.dx(0,1,f)*9.5,dz=worldObj.isRemote?Math.cos(Math.toRadians(rotationYaw))*9.5:LaunchFacilityPlan.dz(0,1,f)*9.5;riddenByEntity.setPosition(posX+(shuttle()?dx:0),posY+getMountedYOffset()+riddenByEntity.getYOffset(),posZ+(shuttle()?dz:0));riddenByEntity.fallDistance=0;}}
    @Override public boolean canBeCollidedWith(){return true;}
    @Override public boolean attackEntityFrom(DamageSource source,float amount){return false;}
    @Override public boolean interactFirst(EntityPlayer p){if(worldObj.isRemote)return true;if(!owner.equals(p.getUniqueID().toString()))return true;if(phase!=LANDED)return true;
        if(control.canister(p))return true;if(p.isSneaking()){recover(p);return true;}p.openGui(dev.industrialtechnology.core.IndustrialTechnology.instance,3,worldObj,getEntityId(),0,0);return true;}
    public boolean launchAgain(EntityPlayerMP p){if(phase!=LANDED||!owner.equals(p.getUniqueID().toString()))return false;owner=p.getUniqueID().toString();if(!prepare(p))return false;p.closeScreen();p.mountEntity(this);syncPassenger(p);return true;}
    private void recover(EntityPlayer p){if(phase!=LANDED)return;ItemStack s=control.items[0];if(s==null)return;NBTTagCompound n=s.getTagCompound();n.setTag("StoredHDD",control.items[1]==null?new NBTTagCompound():control.items[1].writeToNBT(new NBTTagCompound()));n.setInteger("StoredKerosene",control.tanks[0].getFluidAmount());n.setInteger("StoredLOX",control.tanks[1].getFluidAmount());n.setInteger("StoredAir",control.tanks[2].getFluidAmount());FlightLedger.get(worldObj).recover(n.getString("RocketId"),getUniqueID().toString());if(!p.inventory.addItemStackToInventory(s))worldObj.spawnEntityInWorld(new EntityItem(worldObj,posX,posY,posZ,s));control.items[0]=control.items[1]=null;setDead();p.inventory.markDirty();}
    @Override protected void writeEntityToNBT(NBTTagCompound n){NBTTagCompound c=new NBTTagCompound();control.writeToNBT(c);n.setTag("Controller",c);n.setString("Owner",owner);n.setInteger("Phase",phase);n.setInteger("FlightTicks",ticks);n.setInteger("Destination",destination);n.setInteger("BurnCost",burnCost);if(landing!=null)n.setIntArray("Landing",new int[]{landing.posX,landing.posY,landing.posZ});}
    @Override protected void readEntityFromNBT(NBTTagCompound n){control.readFromNBT(n.getCompoundTag("Controller"));control.setWorldObj(worldObj);owner=n.getString("Owner");phase=Math.max(0,Math.min(3,n.getInteger("Phase")));ticks=Math.max(0,n.getInteger("FlightTicks"));destination=n.getInteger("Destination");burnCost=Math.max(0,n.getInteger("BurnCost"));int[] l=n.getIntArray("Landing");landing=l.length==3?new ChunkCoordinates(l[0],l[1],l[2]):null;if(phase!=LANDED&&landing==null)phase=LANDED;updateGeometry();}
}
